const swiper=new Swiper(".mySwiper",{grabCursor:!0,slidesPerView:1,autoHeight:!0,navigation:{nextEl:".swiper-button-next",prevEl:".swiper-button-prev"},pagination:{el:".swiper-pagination",clickable:!0}});document.addEventListener("DOMContentLoaded",(function(){const e=document.querySelector(".sidebarL__list"),t=document.querySelector(".btn-wrapper"),n=document.querySelector(".btn-wrapper .btn.btn-primary"),r=document.querySelector('.sidebarL__item[data-hr-status="current"]');if(!r||!t||!n)return;new IntersectionObserver((function(e){e.forEach((function(e){t.classList.toggle("hidden",e.isIntersecting)}))}),{root:e,threshold:0}).observe(r),n.addEventListener("click",(function(t){t.preventDefault(),function(){const t=r.getBoundingClientRect(),n=e.getBoundingClientRect(),o=t.top-n.top+e.scrollTop;e.scrollTo({top:o,behavior:"smooth"})}()}))}));